function s(){document.querySelectorAll('[data-component="lazy-youtube"]').forEach(t=>{const r=t.getAttribute("data-embed");r&&(t.classList.add("relative","cursor-pointer"),t.insertAdjacentHTML("afterbegin",`
      <div class="play absolute inset-0 flex items-center justify-center cursor-pointer z-10 group" title="Play">
        <div class="w-16 h-16 ui-button ui-focus ui-ease ui-primary backdrop-blur-md flex items-center justify-center">
          <svg class="w-8 h-8" aria-hidden="true"><use href="#icon-play"></use></svg>
        </div>
      </div>
    `),t.addEventListener("click",()=>{const e=document.createElement("iframe");e.src=`https://www.youtube.com/embed/${r}?rel=0&showinfo=0&autoplay=1`,e.title="YouTube video player",e.className="w-full h-full absolute inset-0 border-0 rounded-xl loaded",e.allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",e.referrerPolicy="strict-origin-when-cross-origin",e.allowFullscreen=!0,t.innerHTML="",t.appendChild(e)}))})}export{s as initLazyYoutube};
